param([Parameter(Mandatory=$true)][string]$ArtifactDir)
$ErrorActionPreference='Stop'
$baseWrapper='.\optimizer\scripts\r54_2_game_mutation_acceptance_v6.ps1'
$src=Get-Content $baseWrapper -Raw
$tailNeedle="Write-Host 'R54_2_V6_DIAGNOSTIC_INSTRUMENTATION_READY'"
$tailStart=$src.IndexOf($tailNeedle,[StringComparison]::Ordinal)
if($tailStart-lt0){throw 'R54.2 v7 v6 execution tail missing'}
$b64=''
$replacement=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($b64))
$v7=$src.Substring(0,$tailStart)+$replacement
$tmp=Join-Path $env:RUNNER_TEMP 'r54_2_game_mutation_acceptance_v7_expanded.ps1'
Set-Content $tmp $v7 -Encoding UTF8
& $tmp -ArtifactDir $ArtifactDir
if($LASTEXITCODE-ne0){throw "R54.2 GAME mutation v7 wrapper failed: $LASTEXITCODE"}
